require __DIR__.'/../admin.php';$q=mb_substr(trim($_GET['q']??''),0,100);$results=admin_search_results($q);$groups=[];foreach($results as $r)$groups[$r['type']][]=$r;$type=(string)($_GET['type']??'');if($type!==''&&!isset($groups[$type]))$type='';$hint=null;if(!$results&&preg_match('/^[a-z]{4,20}$/i',$q)){$best=3;foreach(['patient','product','inventory','invoice','consultation','refer','referral','orders','users','appearance','settings'] as $word){$distance=levenshtein(strtolower($q),$word);if($distance<$best){$best=$distance;$hint=$word;}}}admin_console_open('Search');
?>
<section class="sc-search-hero"><h2 class="h4">Find your way around StepCure</h2><p class="text-muted">Search by name, email, record number, or what you want to do.</p><form method="get"><label class="visually-hidden" for="search-main">Search StepCure</label><input class="form-control" id="search-main" type="search" name="q" value="<?= sc_e($q) ?>" minlength="2" maxlength="100" placeholder="Try a patient name, order number or ‘referral’" autofocus><button class="btn btn-primary">Search</button></form><small class="text-muted">Tip: Ctrl/Cmd + K opens header search. Results follow your permissions.</small></section>
<?php if($groups): ?><nav class="sc-search-filters" aria-label="Filter search results"><a href="?<?= sc_e(http_build_query(['q'=>$q])) ?>" <?= $type===''?'aria-current="page"':'' ?>>All (<?= count($results) ?>)</a><?php foreach($groups as $group=>$items): ?><a href="?<?= sc_e(http_build_query(['q'=>$q,'type'=>$group])) ?>" <?= $type===$group?'aria-current="page"':'' ?>><?= sc_e($group) ?> (<?= count($items) ?>)</a><?php endforeach; ?></nav><?php endif; ?>
<?php if(mb_strlen($q)<2): ?><div class="card p-4"><h2 class="h5">What are you looking for?</h2><p>Enter at least two characters, or try one of these shortcuts.</p><div class="d-flex flex-wrap gap-2"><?php foreach(['Patients','Products','Inventory','Orders','Referral','Appearance'] as $example): ?><a class="btn btn-outline-primary" href="?q=<?= $example ?>"><?= $example ?></a><?php endforeach; ?></div></div><?php elseif(!$results): ?><div class="card p-4"><h2 class="h5">No matches for “<?= sc_e($q) ?>”</h2><p>Try a shorter name, an email, or the numeric part of a record number. Some records may be outside your access.</p><?php if($hint): ?><p>Did you mean <a href="?q=<?= sc_e($hint) ?>"><strong><?= sc_e($hint) ?></strong></a>?</p><?php endif; ?></div><?php endif; ?>
<?php foreach($groups as $group=>$items):if($type!==''&&$group!==$type)continue; ?><section class="mb-4"><h2 class="h6 text-uppercase"><?= sc_e($group) ?></h2><?php foreach($items as $r): ?><a class="sc-search-result" href="<?= sc_e($r['url']) ?>"><span aria-hidden="true"><i class="bx <?= $group==='Feature'?'bx-grid-alt':(str_contains($group,'Patient')?'bx-user':'bx-file') ?>"></i></span><div><strong><?= sc_e($r['label']) ?></strong><small><?= sc_e($r['detail']) ?></small></div></a><?php endforeach; ?></section><?php endforeach; ?><p class="text-muted small mt-4">Up to eight matches per category. Documents are found through consultation, invoice and page records; PDF/image contents are not indexed.</p><?php admin_console_close(); ?>
